Clase Contador
  Privado Definir valor Como Entero;

  Metodo Constructor(inicial Como Entero)
    Este.valor <- inicial;
  FinMetodo

  Metodo Actual() Como Entero
    Retornar Este.valor;
  FinMetodo
FinClase

Algoritmo Crear
  Escribir Nuevo Contador(10).Actual();
FinAlgoritmo

Clase Punto
  Definir x Como Entero;
FinClase

Algoritmo SinNuevo
  Definir p Como Punto;
  p.x <- 1;
FinAlgoritmo
